import type { Abi, AbiEvent } from "viem";
import coreArtifact from "../../abi/RunProofCore.json";
import categoryArtifact from "../../abi/CategoryRegistry.json";
import reasonArtifact from "../../abi/ChallengeReasonRegistry.json";
import nftArtifact from "../../abi/RecordNFT.json";

/**
 * ABI artifacts for the V2 deployment. They are generated by `pnpm abi:gen` and verified
 * against the live chain with `pnpm abi:check`; do not hand-edit the JSON files.
 */
export const coreAbi = coreArtifact as unknown as Abi;
export const categoryRegistryAbi = categoryArtifact as unknown as Abi;
export const reasonRegistryAbi = reasonArtifact as unknown as Abi;
export const recordNftAbi = nftArtifact as unknown as Abi;

function selectedEvents(abi: Abi, names: string[]): AbiEvent[] {
  return abi.filter((item): item is AbiEvent => item.type === "event" && names.includes(item.name ?? ""));
}

const coreEvents = selectedEvents(coreAbi, [
  "RecordSubmitted",
  "RecordVerified",
  "RecordRevoked",
  "LeaderboardUpdated",
  "ChallengeCreated",
  "EvidenceSubmitted",
  "VoteCommitted",
  "VoteRevealed",
  "VotingExtended",
  "EvidenceVotingStarted",
  "VotingFinalized",
  "StakeReturned",
  "StakeSlashed",
  "RewardDistributed",
  "Withdrawn",
  "PoolFunded",
  "PoolWithdrawn",
  "ParamsUpdated",
]);
const categoryEvents = selectedEvents(categoryRegistryAbi, [
  "CategoryCreated",
  "CategoryUpdated",
  "CategoryActiveSet",
  "DivisionCreated",
  "DivisionActiveSet",
]);
const reasonEvents = selectedEvents(reasonRegistryAbi, [
  "ReasonRegistered",
  "ReasonProposed",
  "ReasonProposalVoted",
  "ReasonProposalFinalized",
  "DiscovererRewarded",
]);
const nftEvents = selectedEvents(recordNftAbi, ["NFTMinted", "Transfer"]);

export const indexedEvents = [...coreEvents, ...categoryEvents, ...reasonEvents, ...nftEvents];
